// Offline replay of the frames captured by feishu_probe.dart:
// walks the protobuf top-level fields with an INDEPENDENT parser
// (offset trace), then runs PbbpFrame.decode on the same bytes to
// see where the codec derails.

// ignore_for_file: avoid_print

import 'dart:convert';
import 'dart:typed_data';

import 'package:octodo/src/feishu/pbbp_frame.dart';

const pongHex =
    '';

const eventHex =
    '';

Uint8List fromHex(String hex) {
  return Uint8List.fromList([
    for (var i = 0; i < hex.length; i += 2)
      int.parse(hex.substring(i, i + 2), radix: 16),
  ]);
}

/// Independent walker: prints every top-level field with offsets.
void walk(String name, Uint8List d) {
  print('=== $name (${d.length} bytes) — field walk ===');
  var i = 0;
  int varint() {
    final start = i;
    var v = 0;
    var shift = 0;
    while (i < d.length && d[i] & 0x80 != 0) {
      v |= (d[i] & 0x7f) << shift;
      shift += 7;
      i++;
    }
    if (i >= d.length) {
      print('  !! truncated varint at $start');
      return -1;
    }
    v |= d[i] << shift;
    i++;
    return v;
  }

  while (i < d.length) {
    final tagAt = i;
    if (d[i] & 0x80 != 0) {
      // multi-byte tag — the codec only reads one byte!
      print('  !! MULTI-BYTE TAG at offset $tagAt '
          '(byte ${d[i].toRadixString(16)})');
    }
    final tag = d[i++];
    final field = tag >> 3;
    final wire = tag & 7;
    switch (wire) {
      case 0:
        final v = varint();
        print('  @$tagAt field $field varint = $v');
      case 1:
        i += 8;
        print('  @$tagAt field $field fixed64');
      case 2:
        final len = varint();
        print('  @$tagAt field $field len=$len '
            '(payload preview: ${len > 0 && len < 40 ? utf8.decode(Uint8List.sublistView(d, i, i + len), allowMalformed: true) : "…"})');
        i += len;
      case 5:
        i += 4;
        print('  @$tagAt field $field fixed32');
      default:
        print('  !! bad wire type $wire at $tagAt');
        return;
    }
    if (i > d.length) {
      print('  !! OVERRAN buffer (i=$i > ${d.length})');
      return;
    }
  }
  print('  walk complete at $i/${d.length}');

  try {
    final f = PbbpFrame.decode(d);
    print('  PbbpFrame.decode OK: seq=${f.seqId} service=${f.service} '
        'method=${f.method} headers=${f.headers.length} '
        'payload=${f.payload?.length}');
  } on FormatException catch (e) {
    print('  PbbpFrame.decode FAILED: ${e.message}');
  }
}

Future<void> main() async {
  walk('pong', fromHex(pongHex));
  walk('event', fromHex(eventHex));
}
